import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.CTeY_0bQ.js";const m=JSON.parse('{"title":"0002 两种编排模式：外部引擎与会话内编排","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0002-two-orchestration-modes.md","filePath":"reference/adr/0002-two-orchestration-modes.md","lastUpdated":null}'),i={name:"reference/adr/0002-two-orchestration-modes.md"};function s(l,e,d,n,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<div><h1 id="_0002-两种编排模式-外部引擎与会话内编排" tabindex="-1">0002 两种编排模式：外部引擎与会话内编排 <a class="header-anchor" href="#_0002-两种编排模式-外部引擎与会话内编排" aria-label="Permalink to &quot;0002 两种编排模式：外部引擎与会话内编排&quot;">​</a></h1><ul><li>状态：提议（模式 B 依赖一个待验证的假设）</li><li>详见：<a href="./../design/architecture">architecture.md §4</a>、<a href="https://github.com/yiyisf/laoshi/blob/main/docs/design/in-chat-orchestration.md" target="_blank" rel="noreferrer">in-chat-orchestration.md</a></li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>req-kit 的引擎是外部进程，经 SDK 驱动步骤 agent，流程保证最强，但要求平台有程序化 agent API。团队的内部 agent 平台是否具备，目前未知。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ul><li>**模式 A（外部引擎）**为默认，也是流程保证最强的模式。</li><li>提供**模式 B（会话内编排）**覆盖只能接入 skill 的平台：状态机仍在 CLI 里，会话 agent 通过 <code>laoshi run next / record</code> 推进。</li><li>两种模式共用状态文件、结果文件和步骤提示词。</li><li>实现顺序：先做<strong>无头 CLI 运行时</strong>（模式 A 的一个适配器，不改 <code>flow</code>），再做模式 B，且以&quot;续跑机制可复用&quot;的假设验证通过为前提。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><ul><li>文档必须说明模式 B 的流程保证弱于模式 A，让团队按场景选择。</li><li>需要用 <code>fake-runtime</code> 写&quot;外包执行器&quot;来验证假设；验证不通过则需要把 <code>flow</code> 改成显式状态机，工作量显著增加，届时重新评估是否做模式 B。</li></ul></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/laoshi/blob/main/docs/adr/0002-two-orchestration-modes.md">docs/adr/0002-two-orchestration-modes.md</a> 生成。<a href="https://github.com/yiyisf/laoshi/edit/main/docs/adr/0002-two-orchestration-modes.md">在 GitHub 上编辑</a></p>',2)])])}const f=a(i,[["render",s]]);export{m as __pageData,f as default};
